const lockActiveCreditLots = `-- name: LockActiveCreditLots :many
SELECT id, tenant_id, source, period_start, granted, used, starts_at, expires_at, note, reference, created_by, created_at, updated_at FROM ai_credit_lots
WHERE starts_at <= $1 AND (expires_at IS NULL OR expires_at > $1)
ORDER BY (source = 'plan') DESC, expires_at NULLS LAST, created_at, id
FOR UPDATE
`

// The lots usable now, in consumption order (the plan's month first, then
// what expires first), locked against concurrent consumption.
func (q *Queries) LockActiveCreditLots(ctx context.Context, now time.Time) ([]AiCreditLot, error) {
	rows, err := q.db.Query(ctx, lockActiveCreditLots, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AiCreditLot{}
	for rows.Next() {
		var i AiCreditLot
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Source,
			&i.PeriodStart,
			&i.Granted,
			&i.Used,
			&i.StartsAt,
			&i.ExpiresAt,
			&i.Note,
			&i.Reference,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockTenantPlanCounter = `-- name: LockTenantPlanCounter :exec
SELECT pg_advisory_xact_lock(hashtextextended('messora.plan:' || app_tenant_id()::text || ':' || $1::text, 0))
`

// Serialises the creating transactions of one counted resource of the
// tenant (count-then-insert under the same lock).
func (q *Queries) LockTenantPlanCounter(ctx context.Context, resource string) error {
	_, err := q.db.Exec(ctx, lockTenantPlanCounter, resource)
	return err
}

