const upsertPlatformAIModel = `-- name: UpsertPlatformAIModel :exec
INSERT INTO platform_ai_models (provider_id, model_id, display_name, context_window, max_output, capabilities, lifecycle, synced_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (provider_id, model_id) DO UPDATE SET
    display_name = excluded.display_name, context_window = excluded.context_window, max_output = excluded.max_output,
    capabilities = excluded.capabilities, lifecycle = excluded.lifecycle, synced_at = now()
`

type UpsertPlatformAIModelParams struct {
	ProviderID    uuid.UUID
	ModelID       string
	DisplayName   string
	ContextWindow *int64
	MaxOutput     *int64
	Capabilities  []byte
	Lifecycle     *string
}

func (q *Queries) UpsertPlatformAIModel(ctx context.Context, arg UpsertPlatformAIModelParams) error {
	_, err := q.db.Exec(ctx, upsertPlatformAIModel,
		arg.ProviderID,
		arg.ModelID,
		arg.DisplayName,
		arg.ContextWindow,
		arg.MaxOutput,
		arg.Capabilities,
		arg.Lifecycle,
	)
	return err
}
